<script setup>
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue';
import Icon from './HelmLabIcon.vue';
const props=defineProps({pkg:{type:Object,required:true},session:{type:Object,required:true},request:{type:Function,required:true},busy:Boolean,caseId:{type:String,default:''},stepId:{type:String,default:''}});
const emit=defineEmits(['capture','close']);
const state=ref(null),loading=ref(false),error=ref(''),component=ref('rancher'),selected=ref('');
const draft=reactive({tailLines:1000,sinceSeconds:900,previous:false,description:'',caseId:props.caseId,stepId:props.stepId});
let disposed=false;
const targetKey=target=>`${target.podUid}/${target.container}`;
const targets=computed(()=>(state.value?.targets||[]).filter(target=>target.component===component.value));
const target=computed(()=>targets.value.find(item=>targetKey(item)===selected.value));
const steps=computed(()=>props.session.cases.find(item=>item.id===draft.caseId)?.steps||[]);
function chooseComponent(value){component.value=value;selected.value=targets.value.length===1?targetKey(targets.value[0]):'';}
async function refresh(){if(loading.value||props.busy)return;loading.value=true;error.value='';try{const result=await props.request('log-targets',{id:props.pkg.id,revision:props.pkg.revision,sessionId:props.session.id});if(disposed)return;state.value=result;if(!(result.targets||[]).some(item=>item.component===component.value))component.value=result.targets?.[0]?.component||'rancher';if(!targets.value.some(item=>targetKey(item)===selected.value))selected.value=targets.value.length===1?targetKey(targets.value[0]):'';}catch(err){if(!disposed){state.value=null;error.value=err.message;}}finally{if(!disposed)loading.value=false;}}
function capture(){if(!target.value||loading.value||props.busy)return;emit('capture',{...draft,pod:target.value.pod,podUid:target.value.podUid,container:target.value.container});}
onMounted(refresh);
onBeforeUnmount(()=>{disposed=true;});
</script>
<template>
  <form class="package-log-capture" aria-label="Capture pod log snapshot" tabindex="-1" @submit.prevent="capture">
    <header><span class="plc-emblem"><Icon name="terminal"/></span><div><span class="plc-eyebrow">CAPTURE THE MOMENT</span><h4>Get a log snapshot</h4><p>{{session.environment.clusterName||'Session cluster'}} · cattle-system</p></div><button type="button" class="plc-close" :disabled="busy" aria-label="Close log snapshot" @click="$emit('close')"><Icon name="close"/></button></header>
    <p class="plc-intro">Read a container’s recent logs and keep a copy with this investigation. Each snapshot records the pod identity, image, time window, and capture time.</p>
    <div v-if="error" class="plc-message plc-error" role="alert">{{error}}</div>
    <div v-if="loading" class="plc-message" role="status"><Icon name="refresh"/>Finding Rancher and webhook containers…</div>
    <div v-else-if="state&&!state.available" class="plc-message"><Icon name="signal"/><span>{{state.reason||'No accessible Rancher or webhook containers were found for this session.'}}</span></div>
    <template v-if="state?.available&&!loading">
      <div class="plc-target-bar"><div class="plc-segmented" role="group" aria-label="Log source"><button v-for="item in [{id:'rancher',label:'Rancher'},{id:'webhook',label:'Webhook'}]" :key="item.id" type="button" :aria-pressed="component===item.id" :disabled="busy" @click="chooseComponent(item.id)"><Icon :name="item.id==='rancher'?'server':'pulse'"/>{{item.label}}<span>{{state.targets.filter(target=>target.component===item.id).length}}</span></button></div><button type="button" class="plc-link" :disabled="busy" @click="refresh"><Icon name="refresh"/>Refresh pods</button></div>
      <label>Pod / container<select v-model="selected" required :disabled="busy||!targets.length"><option value="">{{targets.length?'Choose a container…':'No containers found for this component'}}</option><option v-for="item in targets" :key="targetKey(item)" :value="targetKey(item)">{{item.pod}} / {{item.container}}{{item.ready?'':' · not ready'}}</option></select></label>
      <div v-if="target" class="plc-target"><Icon name="fingerprint"/><div><code>{{target.image}}</code><small>{{target.ready?'Ready':'Not ready'}} · {{target.restarts||0}} restarts · UID {{target.podUid}}</small></div></div>
      <div class="plc-fields"><label>Time window<select v-model.number="draft.sinceSeconds" :disabled="busy"><option :value="300">Last 5 minutes</option><option :value="900">Last 15 minutes</option><option :value="3600">Last hour</option><option :value="21600">Last 6 hours</option><option :value="86400">Last 24 hours</option></select></label><label>Maximum lines<select v-model.number="draft.tailLines" :disabled="busy"><option :value="200">200 lines</option><option :value="1000">1,000 lines</option><option :value="5000">5,000 lines</option><option :value="10000">10,000 lines</option></select></label></div>
      <div class="plc-fields"><label>Attach to<select v-model="draft.caseId" :disabled="busy" @change="draft.stepId=''"><option value="">Entire session</option><option v-for="item in session.cases" :key="item.id" :value="item.id">{{item.title}}</option></select></label><label v-if="draft.caseId"><span class="plc-label">Step <small>optional</small></span><select v-model="draft.stepId" :disabled="busy"><option value="">Entire case</option><option v-for="(step,index) in steps" :key="step.id" :value="step.id">Step {{index+1}} · {{step.instruction.slice(0,80)}}</option></select></label></div>
      <label><span class="plc-label">What are you investigating? <small>optional</small></span><textarea v-model="draft.description" rows="2" maxlength="32000" :disabled="busy" placeholder="e.g. Webhook admission response immediately after step 3"/></label>
      <label class="plc-check"><input v-model="draft.previous" type="checkbox" :disabled="busy"/><span>Read the previous container instance<small>Useful after a restart. Kubernetes must still have its logs.</small></span></label>
      <p class="plc-footnote">Snapshot only; no live stream. Up to 4 MiB of retained logs. Recognizable credentials are redacted, but review logs before sharing.</p>
    </template>
    <footer><button v-if="state?.available" type="submit" class="plc-primary" :disabled="busy||loading||!target"><Icon :name="busy?'clock':'download'"/>{{busy?'Capturing snapshot…':'Capture & attach'}}</button><button v-else type="button" :disabled="loading||busy" @click="refresh"><Icon name="refresh"/>Try again</button><button type="button" :disabled="busy" @click="$emit('close')">Cancel</button><span v-if="busy" role="status">Reading logs and saving a package-owned copy…</span></footer>
  </form>
</template>
<style scoped>
.package-log-capture{background:var(--runway-soft);border:1px solid color-mix(in srgb,var(--runway-accent) 40%,var(--runway-border));border-radius:14px;padding:24px;margin-bottom:22px;color:var(--runway-ink)}.package-log-capture header{display:flex;gap:13px;align-items:center}.plc-emblem{width:42px;height:42px;display:grid;place-items:center;background:var(--runway-accent-soft);border-radius:12px;color:var(--runway-accent)}.plc-emblem svg{width:22px;height:22px}.plc-eyebrow{font-size:9px;letter-spacing:.14em;color:var(--runway-muted);font-weight:650}.package-log-capture h4{font-size:19px;font-weight:600;letter-spacing:-.025em;margin:4px 0}.package-log-capture header p{margin:0;font-size:10px;color:var(--runway-muted);overflow-wrap:anywhere}.package-log-capture header>div{min-width:0;flex:1}.package-log-capture button{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--runway-border);border-radius:8px;padding:9px 12px;font:inherit;font-size:11px;background:var(--runway-input);color:var(--runway-ink);cursor:pointer}.package-log-capture button:hover:not(:disabled){border-color:var(--runway-accent)}.package-log-capture button:disabled{opacity:.45;cursor:not-allowed}.package-log-capture button svg{width:14px;height:14px}.package-log-capture .plc-close{background:none;align-self:flex-start;padding:7px;border-color:transparent}.plc-intro{font-size:12px;line-height:1.8;color:var(--runway-muted);margin:18px 0 22px;max-width:720px}.plc-message{display:flex;align-items:flex-start;gap:9px;font-size:12px;line-height:1.8;padding:14px;border:1px solid var(--runway-border);border-radius:9px;margin:15px 0}.plc-message svg{width:17px;height:17px;flex-shrink:0;margin-top:2px}.plc-error{color:var(--runway-error)}.plc-target-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:19px}.plc-segmented{display:flex;gap:4px;padding:4px;background:var(--runway-input);border:1px solid var(--runway-border);border-radius:11px}.plc-segmented button{border-color:transparent;background:none}.plc-segmented button[aria-pressed=true]{background:var(--runway-accent-soft);color:var(--runway-accent);border-color:var(--runway-border)}.plc-segmented button span{font-size:10px;opacity:.75}.package-log-capture .plc-link{color:var(--runway-accent);background:none;border:0;padding:5px}.package-log-capture label{display:grid;gap:7px;font-size:12px;font-weight:550;margin:0 0 18px}.package-log-capture label>span:not(:last-child){font-size:10px;font-weight:400;color:var(--runway-muted)}.package-log-capture select,.package-log-capture textarea{width:100%;min-width:0;background:var(--runway-input);border:1px solid var(--runway-control);border-radius:9px;padding:11px 12px;font:inherit;font-weight:400;line-height:1.6;color:var(--runway-ink);resize:vertical}.package-log-capture :focus-visible{outline:2px solid var(--runway-accent);outline-offset:3px}.plc-target{display:flex;gap:10px;margin:-4px 0 19px;padding:11px 13px;background:var(--runway-input);border-radius:9px}.plc-target>svg{width:17px;height:17px;flex-shrink:0;color:var(--runway-accent)}.plc-target>div{min-width:0}.plc-target code{font:10px/1.7 ui-monospace,monospace;display:block;overflow-wrap:anywhere}.plc-target small{font-size:9px;line-height:1.8;color:var(--runway-muted);overflow-wrap:anywhere;display:block;margin-top:4px}.plc-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:17px}.package-log-capture .plc-check{display:flex;gap:9px;align-items:flex-start;font-size:11px}.plc-check input{margin-top:2px;accent-color:var(--runway-accent)}.plc-check small{display:block;font-size:10px;font-weight:400;color:var(--runway-muted);margin-top:5px}.plc-footnote{font-size:10px;line-height:1.8;color:var(--runway-muted);margin:10px 0 18px}.package-log-capture footer{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding-top:16px;border-top:1px solid var(--runway-border)}.package-log-capture .plc-primary{background:var(--runway-accent);color:var(--runway-soft);border-color:var(--runway-accent);font-weight:600}.package-log-capture footer>span{font-size:10px;color:var(--runway-muted)}@media(max-width:650px){.package-log-capture{padding:18px}.plc-fields{grid-template-columns:1fr;gap:0}.package-log-capture footer>span{width:100%}}
.package-log-capture .plc-label{font-size:12px!important;font-weight:550!important;color:var(--runway-ink)!important}.plc-label small{font-size:10px;font-weight:400;color:var(--runway-muted);margin-left:4px}
</style>
